package December17;

public class largestof3 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a = 80;
		int b = 40;
		int c = 30;
		
		if(a>b && a>c){
			System.out.println(a + " is largest");
		}else if(b>c){
			System.out.println(b + " is largest");			
		}else{
			System.out.println(c + " is largest");
		}

	}

}
